{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>{{BUSINESS_NAME}} — About</title>
  <meta name="description" content="The story, philosophy, and approach behind {{BUSINESS_NAME}}. A playful-premium wellness experience blending science-backed coaching with joyful habits." />
  <style>
    :root{
      --clr-teal:#0f4c5c; /* deep teal */
      --clr-teal-ink:#0b2a2f;
      --clr-sand:#e6d6b5; /* sand */
      --clr-cream:#fbf9f6; /* off-white */
      --clr-accent:#ff8a5b; /* tasteful accent */
      --clr-mint:#d0efe7;
      --radius-xl:28px;
      --radius-lg:20px;
      --radius-md:14px;
      --shadow-sm:0 4px 14px rgba(15,76,92,.08);
      --shadow-md:0 10px 28px rgba(15,76,92,.12);
      --shadow-lg:0 18px 48px rgba(15,76,92,.18);
    }
    html{scroll-behavior:smooth}
    body{margin:0;font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";color:var(--clr-teal-ink);background:var(--clr-cream);line-height:1.6}
    .skip-link{position:absolute;left:-999px;top:auto;width:1px;height:1px;overflow:hidden}
    .skip-link:focus{position:fixed;left:16px;top:16px;width:auto;height:auto;padding:10px 14px;background:#fff;border-radius:10px;box-shadow:var(--shadow-sm);z-index:10000}

    /* Layout */
    .wrap{max-width:1120px;margin-inline:auto;padding:0 20px}

    /* Header */
    header.site-header{position:sticky;top:0;z-index:50;background:linear-gradient(180deg,#ffffffE6,#ffffffCC), url('assets/img/pattern.svg');backdrop-filter:saturate(1.2) blur(6px);border-bottom:1px solid rgba(15,76,92,.06)}
    .nav{display:flex;align-items:center;justify-content:space-between;padding:14px 0}
    .brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--clr-teal-ink)}
    .brand-logo{width:40px;height:40px;border-radius:12px;background:radial-gradient(circle at 30% 30%, var(--clr-accent), transparent 55%), radial-gradient(circle at 70% 60%, var(--clr-mint), transparent 60%), var(--clr-teal);box-shadow:inset 0 0 0 2px rgba(255,255,255,.6), var(--shadow-sm)}
    .brand-title{font-weight:800;letter-spacing:.2px;font-size:1.1rem}

    .nav-links{display:flex;align-items:center;gap:18px}
    .nav-links a{color:var(--clr-teal-ink);text-decoration:none;font-weight:600;padding:8px 10px;border-radius:10px}
    .nav-links a:hover{background:rgba(15,76,92,.06)}
    .cta{background:var(--clr-accent);color:#092023;padding:10px 14px;border-radius:12px;font-weight:800;box-shadow:var(--shadow-sm);border:2px solid #ffb79d}
    .cta:hover{transform:translateY(-1px);box-shadow:var(--shadow-md)}

    .nav-toggle{display:none;background:var(--clr-teal);color:#fff;border:0;padding:10px 12px;border-radius:12px}

    @media (max-width: 860px){
      .nav-links{position:fixed;inset:64px 16px auto 16px;background:#ffffff;border:1px solid rgba(15,76,92,.08);border-radius:16px;box-shadow:var(--shadow-lg);padding:14px;display:none;flex-wrap:wrap}
      .nav-links.open{display:flex}
      .nav-links a{flex:1 1 calc(50% - 12px);background:rgba(15,76,92,.04);margin:6px;border-radius:10px;text-align:center}
      .nav-toggle{display:inline-flex;align-items:center;gap:8px}
    }

    /* Hero */
    .hero{position:relative;isolation:isolate;padding:64px 0 24px;background:linear-gradient(180deg, #fefefe 0%, #fbf9f6 100%)}
    .hero .wrap{display:grid;grid-template-columns: 1.15fr .85fr;gap:28px;align-items:center}
    .hero-art{position:relative}
    .hero-art::after{content:"";position:absolute;inset:auto -24px -24px -24px;height:42%;background:linear-gradient(135deg, var(--clr-sand), #fff);border-radius:24px 24px var(--radius-xl) var(--radius-xl);z-index:-1;box-shadow:var(--shadow-md)}
    .hero img{width:100%;height:auto;display:block}
    .eyebrow{display:inline-flex;align-items:center;gap:8px;background:rgba(15,76,92,.08);padding:6px 10px;border-radius:999px;font-weight:700}
    .eyebrow::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--clr-accent)}
    h1{font-size:clamp(2rem, 4vw, 3rem);line-height:1.15;margin:14px 0 10px}
    .sub{font-size:1.1rem;color:#2b3e43}
    .hero-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}
    .btn{appearance:none;border:0;padding:12px 16px;border-radius:14px;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:10px}
    .btn-primary{background:var(--clr-teal);color:#fff;box-shadow:var(--shadow-md)}
    .btn-primary:hover{filter:brightness(1.05);transform:translateY(-1px)}
    .btn-secondary{background:var(--clr-sand);color:#2b3e43}

    @media (max-width: 900px){
      .hero .wrap{grid-template-columns:1fr}
      .hero-art{order:-1}
    }

    /* Sections */
    section{padding:56px 0}
    .section-title{font-size:1.8rem;margin:0 0 10px}
    .section-kicker{color:#33565c;font-weight:800;letter-spacing:.8px;text-transform:uppercase;font-size:.85rem}

    /* About grid */
    .about-grid{display:grid;grid-template-columns: 1.1fr .9fr;gap:26px}
    .about-card{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:var(--radius-xl);padding:22px;box-shadow:var(--shadow-sm)}
    .about-card.accent{background:linear-gradient(160deg,#ffffff, #fff7ef 60%);border-color:#ffd8c8}
    .about-card h3{margin:0 0 8px}
    .badge{display:inline-flex;align-items:center;gap:6px;background:rgba(255,138,91,.12);color:#7a3a23;border:1px dashed #ffb79d;padding:6px 10px;border-radius:999px;font-weight:700;font-size:.9rem}

    @media (max-width: 900px){.about-grid{grid-template-columns:1fr}}

    /* Benefits */
    .benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
    .benefit{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:18px;padding:18px;box-shadow:var(--shadow-sm);display:grid;grid-template-columns:auto 1fr;gap:14px}
    .benefit-icon{width:42px;height:42px;border-radius:12px;background:radial-gradient(circle at 35% 35%, var(--clr-accent), transparent 55%), var(--clr-mint)}
    .benefit strong{font-size:1.05rem}
    @media (max-width: 860px){.benefits{grid-template-columns:1fr}}

    /* Tiers */
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
    .tier{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:22px;padding:20px;box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
    .tier::after{content:"";position:absolute;right:-28px;top:-28px;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle at 30% 30%, #ffffffAA, transparent 60%), var(--clr-sand);filter:blur(2px)}
    .tier h4{margin:0 0 6px}
    .pill{display:inline-block;background:rgba(15,76,92,.08);padding:4px 8px;border-radius:999px;font-weight:700;font-size:.8rem}
    .tier ul{padding-left:18px;margin:12px 0}
    .tier .btn{margin-top:8px}
    .tier.featured{border:2px solid var(--clr-accent);box-shadow:var(--shadow-md)}
    @media (max-width: 1000px){.tiers{grid-template-columns:1fr 1fr}}
    @media (max-width: 720px){.tiers{grid-template-columns:1fr}}

    /* Testimonials */
    .testi{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
    .quote{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:20px;padding:18px;box-shadow:var(--shadow-sm)}
    .quote p{margin:0 0 10px}
    .person{display:flex;align-items:center;gap:10px}
    .avatar{width:42px;height:42px;border-radius:50%;background:url('assets/img/avatar.svg') center/cover no-repeat, var(--clr-sand);border:2px solid #fff;box-shadow:var(--shadow-sm)}
    @media (max-width: 860px){.testi{grid-template-columns:1fr}}

    /* FAQ */
    .faq{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .faq .q{background:#fff;border:1px solid rgba(15,76,92,.1);border-radius:16px}
    .faq button{all:unset;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 16px;cursor:pointer}
    .faq button:focus-visible{outline:3px solid var(--clr-accent);border-radius:14px}
    .faq .icon{flex:0 0 34px;height:34px;border-radius:10px;background:var(--clr-mint);display:grid;place-items:center;font-weight:900;color:#1c3f46}
    .faq .a{max-height:0;overflow:hidden;transition:max-height .28s ease}
    .faq .a-inner{padding:0 16px 14px}
    .faq .open .a{max-height:260px}
    @media (max-width: 900px){.faq{grid-template-columns:1fr}}

    /* Newsletter */
    .newsletter{background:linear-gradient(135deg, #fefefe, #fff7ef);border:1px solid #ffe2d6;border-radius:22px;padding:20px;display:grid;grid-template-columns:1.2fr .8fr;gap:16px;box-shadow:var(--shadow-sm)}
    .newsletter form{display:flex;gap:10px;flex-wrap:wrap}
    .field{flex:1 1 220px;min-width:200px}
    input[type=email]{width:100%;padding:12px 14px;border-radius:12px;border:1px solid rgba(15,76,92,.18);font:inherit}
    .hint{font-size:.85rem;color:#8a4b38}
    @media (max-width: 860px){.newsletter{grid-template-columns:1fr}}

    /* CTA Banner */
    .cta-banner{background:linear-gradient(90deg, var(--clr-teal), #145d70);color:#eafff8;border-radius:24px;padding:22px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:14px}
    .cta-banner .btn{background:#fff;color:#0f3942}
    @media (max-width: 720px){.cta-banner{grid-template-columns:1fr}}

    /* Footer */
    footer{padding:36px 0 56px}
    .foot{display:grid;grid-template-columns:1.2fr .8fr;gap:20px}
    .foot .mini{display:grid;gap:8px}
    .foot a{color:var(--clr-teal-ink)}
    .small{font-size:.92rem;color:#375a60}
    @media (max-width: 900px){.foot{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header" role="banner">
    <div class="wrap nav">
      <a class="brand" href="index.html">
        <span class="brand-logo" aria-hidden="true"></span>
        <span class="brand-title">{{BUSINESS_NAME}}</span>
      </a>
      <button class="nav-toggle" aria-expanded="false" aria-controls="primary-navigation">Menu</button>
      <nav id="primary-navigation" class="nav-links" aria-label="Primary">
        <a href="index.html">Home</a>
        <a href="about.html" aria-current="page">About</a>
        <a href="services.html">Services</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Pricing</a>
        <a href="testimonials.html">Testimonials</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}" aria-label="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main id="main">
    <section class="hero">
      <div class="wrap">
        <div>
          <span class="eyebrow">Playful premium care</span>
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="sub">{{TAGLINE}} — Our studio blends science-backed coaching with joyful habit design so your healthiest life feels artful, not arduous.</p>
          <div class="hero-cta">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn btn-secondary" href="#about-story">Explore our story</a>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true">
          <img src="assets/img/hero.svg" alt="Abstract playful shapes in deep teal, sand, and off-white" />
        </div>
      </div>
    </section>

    <section id="about-story">
      <div class="wrap about-grid">
        <article class="about-card accent">
          <p class="badge">Rooted in coastal calm</p>
          <h2 class="section-title">Our origin story</h2>
          <p>Born on a windswept shoreline and refined in the bustle of the city, our approach pairs the <em>ease of nature</em> with <em>clarity of strategy</em>. At Salt & Sage Wellness Club, we believe progress is a mood: warm, confident, and a little playful.</p>
          <p>We designed this space to feel like a boutique members club for your wellbeing — quiet lux textures, bold shapes, and coaching that meets you exactly where you are.</p>
        </article>
        <aside class="about-card">
          <h3>Meet your coach</h3>
          <p><strong>{{COACH_NAME}}, {{CREDENTIALS}}</strong></p>
          <p>Part behavior scientist, part hype friend. Expect strategic frameworks, compassionate accountability, and weekly rituals that stick even on your busiest days.</p>
          <ul>
            <li>Specialties: stress resilience, metabolic health, mindful nutrition</li>
            <li>Methods: habit stacking, gentle periodization, values-centered planning</li>
            <li>Vibe: clear, candid, and celebratory</li>
          </ul>
        </aside>
      </div>
    </section>

    <section aria-labelledby="benefits">
      <div class="wrap">
        <p class="section-kicker">Why it works</p>
        <h2 id="benefits" class="section-title">Benefits you can feel</h2>
        <div class="benefits">
          <div class="benefit">
            <div class="benefit-icon" aria-hidden="true"></div>
            <div>
              <strong>Design-first habits</strong>
              <p>Make routines that look good on your calendar and feel even better in your body.</p>
            </div>
          </div>
          <div class="benefit">
            <div class="benefit-icon" aria-hidden="true"></div>
            <div>
              <strong>Personalized, not prescriptive</strong>
              <p>Your plan flexes with travel, seasons, and energy — because life does.</p>
            </div>
          </div>
          <div class="benefit">
            <div class="benefit-icon" aria-hidden="true"></div>
            <div>
              <strong>Calm accountability</strong>
              <p>Weekly check-ins, tasteful nudges, and celebrations that keep momentum gentle and steady.</p>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section aria-labelledby="tiers">
      <div class="wrap">
        <p class="section-kicker">Program tiers</p>
        <h2 id="tiers" class="section-title">Choose your coaching cadence</h2>
        <div class="tiers">
          <div class="tier">
            <span class="pill">Starter</span>
            <h4>Reset</h4>
            <p>Four weeks to refresh routines and rebuild energy.</p>
            <ul>
              <li>1:1 kickoff + close-out sessions</li>
              <li>Weekly text check-ins</li>
              <li>Habit map + calendar templates</li>
            </ul>
            <a class="btn btn-secondary" href="programs.html">See details</a>
          </div>
          <div class="tier featured">
            <span class="pill">Most loved</span>
            <h4>Thrive</h4>
            <p>Three months of guided momentum with monthly deep dives.</p>
            <ul>
              <li>Bi-weekly 1:1 sessions</li>
              <li>Personalized nutrition playbook</li>
              <li>Voice-note support between calls</li>
            </ul>
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
          <div class="tier">
            <span class="pill">Signature</span>
            <h4>Studio</h4>
            <p>Six months, concierge-level support for big-life seasons.</p>
            <ul>
              <li>Weekly 1:1s + on-demand slots</li>
              <li>Lab panels coordination</li>
              <li>Custom recovery + movement cycles</li>
            </ul>
            <a class="btn btn-secondary" href="programs.html">Apply now</a>
          </div>
        </div>
      </div>
    </section>

    <section aria-labelledby="love-notes">
      <div class="wrap">
        <p class="section-kicker">Client words</p>
        <h2 id="love-notes" class="section-title">Testimonials that make us blush</h2>
        <div class="testi">
          <figure class="quote">
            <p>For the first time, my wellness plan feels like it was designed for my actual life. Elegant, doable, effective.</p>
            <figcaption class="person"><span class="avatar" aria-hidden="true"></span> Maya R., product lead</figcaption>
          </figure>
          <figure class="quote">
            <p>The weekly rituals are tiny but mighty. I have steadier energy and more creative focus by noon every day.</p>
            <figcaption class="person"><span class="avatar" aria-hidden="true"></span> Leon T., architect</figcaption>
          </figure>
          <figure class="quote">
            <p>I came for nutrition help and stayed for the calm accountability. Best investment I made this year.</p>
            <figcaption class="person"><span class="avatar" aria-hidden="true"></span> Priya K., founder</figcaption>
          </figure>
        </div>
      </div>
    </section>

    <section aria-labelledby="faq">
      <div class="wrap">
        <p class="section-kicker">Good to know</p>
        <h2 id="faq" class="section-title">FAQ</h2>
        <div class="faq" role="list">
          <div class="q" role="listitem">
            <button aria-expanded="false" aria-controls="a1"><span class="icon">?</span><strong>Is this a diet plan?</strong></button>
            <div id="a1" class="a" role="region" aria-hidden="true">
              <div class="a-inner">No. We design nourishing patterns you can keep. Think better meals, sleep, stress care — not restriction.</div>
            </div>
          </div>
          <div class="q" role="listitem">
            <button aria-expanded="false" aria-controls="a2"><span class="icon">?</span><strong>How are sessions held?</strong></button>
            <div id="a2" class="a" role="region" aria-hidden="true">
              <div class="a-inner">Virtual by default with an in-person option in our studio on select Fridays. Flexible scheduling for different time zones.</div>
            </div>
          </div>
          <div class="q" role="listitem">
            <button aria-expanded="false" aria-controls="a3"><span class="icon">?</span><strong>Do you coordinate with my doctor?</strong></button>
            <div id="a3" class="a" role="region" aria-hidden="true">
              <div class="a-inner">Yes, with your consent. We happily align on labs, medications, and care plans to keep things seamless.</div>
            </div>
          </div>
          <div class="q" role="listitem">
            <button aria-expanded="false" aria-controls="a4"><span class="icon">?</span><strong>What if I travel a lot?</strong></button>
            <div id="a4" class="a" role="region" aria-hidden="true">
              <div class="a-inner">We build modular rituals and travel kits so your routines stay light and portable. Momentum, minus the pressure.</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section aria-labelledby="lead" class="wrap">
      <div class="newsletter" role="region" aria-labelledby="lead-title">
        <div>
          <p class="section-kicker" id="lead-title">Free mini-guide</p>
          <h3 class="section-title">The Rituals Playbook</h3>
          <p class="small">Five 10-minute practices to reset energy and focus. Lovely on a Sunday; powerful by Thursday.</p>
        </div>
        <form id="newsletter-form" novalidate>
          <label class="field">
            <span class="small">Email</span>
            <input type="email" name="email" required placeholder="you@domain.com" aria-describedby="news-hint" />
          </label>
          <button class="btn btn-primary" type="submit">Send the playbook</button>
          <div class="hint" id="news-hint" role="status" aria-live="polite"></div>
        </form>
      </div>
    </section>

    <section aria-label="Booking call" class="wrap" style="margin-top:26px">
      <div class="cta-banner">
        <div>
          <h3 style="margin:0 0 6px">Ready when you are</h3>
          <p class="small" style="margin:0">Book a chemistry call. Bring your questions; we’ll bring tea and a clear next step.</p>
        </div>
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>
  </main>

  <footer role="contentinfo">
    <div class="wrap foot">
      <div>
        <a class="brand" href="index.html"><span class="brand-logo" aria-hidden="true"></span><span class="brand-title">{{BUSINESS_NAME}}</span></a>
        <p class="small">A boutique approach to wellbeing — where structure meets softness and results feel like relief.</p>
      </div>
      <div class="mini">
        <strong>Contact</strong>
        <p class="small">{{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p class="small">{{ADDRESS}}, {{CITY}}, {{STATE}} {{ZIP}}</p>
        <p class="small">Hours: {{HOURS}}</p>
      </div>
    </div>
  </footer>

  <script>
    (function(){
      const navToggle = document.querySelector('.nav-toggle');
      const nav = document.getElementById('primary-navigation');
      if(navToggle && nav){
        navToggle.addEventListener('click', ()=>{
          const open = nav.classList.toggle('open');
          navToggle.setAttribute('aria-expanded', open);
          if(open){ nav.querySelector('a')?.focus(); }
        });
      }

      // Smooth scroll for in-page anchors (respects reduced motion)
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      document.querySelectorAll('a[href^="#"]').forEach(a=>{
        a.addEventListener('click', e=>{
          const id = a.getAttribute('href');
          if(id && id.length > 1){
            const el = document.querySelector(id);
            if(el){
              e.preventDefault();
              if(prefersReduced){ el.scrollIntoView(); }
              else { el.scrollIntoView({behavior:'smooth', block:'start'}); }
              el.setAttribute('tabindex','-1'); el.focus({preventScroll:true});
            }
          }
        });
      });

      // FAQ accordion
      document.querySelectorAll('.faq .q').forEach((item, idx)=>{
        const btn = item.querySelector('button');
        const panel = item.querySelector('.a');
        btn?.addEventListener('click', ()=>{
          const open = item.classList.toggle('open');
          btn.setAttribute('aria-expanded', open);
          panel?.setAttribute('aria-hidden', !open);
        });
      });

      // Newsletter validation hints
      const form = document.getElementById('newsletter-form');
      if(form){
        const email = form.querySelector('input[type="email"]');
        const hint = document.getElementById('news-hint');
        const ok = msg=>{ hint.textContent = msg; hint.style.color = '#1b5e20'; };
        const warn = msg=>{ hint.textContent = msg; hint.style.color = '#7a3a23'; };
        form.addEventListener('submit', e=>{
          e.preventDefault();
          if(!email.value || !email.checkValidity()){
            warn('Please enter a valid email to receive your playbook.');
            email.focus();
          } else {
            ok('Got it! Check your inbox for a download link.');
            form.reset();
          }
        });
        email?.addEventListener('input', ()=>{
          if(email.value && email.checkValidity()) warn('Looks good — ready to send.');
          else hint.textContent = '';
        });
      }
    })();
  </script>
</body>
</html>"}
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Services</title>
