  <style>
    :root{
      --clr-teal:#0f4c5c; /* deep teal */
      --clr-teal-ink:#0b2a2f;
      --clr-sand:#e6d6b5; /* sand */
      --clr-cream:#fbf9f6; /* off-white */
      --clr-accent:#ff8a5b; /* tasteful accent */
      --clr-mint:#d0efe7;
      --radius-xl:28px;
      --radius-lg:20px;
      --radius-md:14px;
      --shadow-sm:0 4px 14px rgba(15,76,92,.08);
      --shadow-md:0 10px 28px rgba(15,76,92,.12);
      --shadow-lg:0 18px 48px rgba(15,76,92,.18);
    }
    html{scroll-behavior:smooth}
    body{margin:0;font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";color:var(--clr-teal-ink);background:var(--clr-cream);line-height:1.6}
    .skip-link{position:absolute;left:-999px;top:auto;width:1px;height:1px;overflow:hidden}
    .skip-link:focus{position:fixed;left:16px;top:16px;width:auto;height:auto;padding:10px 14px;background:#fff;border-radius:10px;box-shadow:var(--shadow-sm);z-index:10000}

    .wrap{max-width:1120px;margin-inline:auto;padding:0 20px}

    header.site-header{position:sticky;top:0;z-index:50;background:linear-gradient(180deg,#ffffffE6,#ffffffCC), url('assets/img/pattern.svg');backdrop-filter:saturate(1.2) blur(6px);border-bottom:1px solid rgba(15,76,92,.06)}
    .nav{display:flex;align-items:center;justify-content:space-between;padding:14px 0}
    .brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--clr-teal-ink)}
    .brand-logo{width:40px;height:40px;border-radius:12px;background:radial-gradient(circle at 30% 30%, var(--clr-accent), transparent 55%), radial-gradient(circle at 70% 60%, var(--clr-mint), transparent 60%), var(--clr-teal);box-shadow:inset 0 0 0 2px rgba(255,255,255,.6), var(--shadow-sm)}
    .brand-title{font-weight:800;letter-spacing:.2px;font-size:1.1rem}

    .nav-links{display:flex;align-items:center;gap:18px}
    .nav-links a{color:var(--clr-teal-ink);text-decoration:none;font-weight:600;padding:8px 10px;border-radius:10px}
    .nav-links a:hover{background:rgba(15,76,92,.06)}
    .cta{background:var(--clr-accent);color:#092023;padding:10px 14px;border-radius:12px;font-weight:800;box-shadow:var(--shadow-sm);border:2px solid #ffb79d}
    .cta:hover{transform:translateY(-1px);box-shadow:var(--shadow-md)}

    .nav-toggle{display:none;background:var(--clr-teal);color:#fff;border:0;padding:10px 12px;border-radius:12px}

    @media (max-width: 860px){
      .nav-links{position:fixed;inset:64px 16px auto 16px;background:#ffffff;border:1px solid rgba(15,76,92,.08);border-radius:16px;box-shadow:var(--shadow-lg);padding:14px;display:none;flex-wrap:wrap}
      .nav-links.open{display:flex}
      .nav-links a{flex:1 1 calc(50% - 12px);background:rgba(15,76,92,.04);margin:6px;border-radius:10px;text-align:center}
      .nav-toggle{display:inline-flex;align-items:center;gap:8px}
    }

    .hero{position:relative;isolation:isolate;padding:64px 0 24px;background:linear-gradient(180deg, #fefefe 0%, #fbf9f6 100%)}
    .hero .wrap{display:grid;grid-template-columns: 1.05fr .95fr;gap:28px;align-items:center}
    .hero-art{position:relative}
    .hero-art::after{content:"";position:absolute;inset:auto -24px -24px -24px;height:42%;background:linear-gradient(135deg, var(--clr-sand), #fff);border-radius:24px 24px var(--radius-xl) var(--radius-xl);z-index:-1;box-shadow:var(--shadow-md)}
    .hero img{width:100%;height:auto;display:block}
    .eyebrow{display:inline-flex;align-items:center;gap:8px;background:rgba(15,76,92,.08);padding:6px 10px;border-radius:999px;font-weight:700}
    .eyebrow::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--clr-accent)}
    h1{font-size:clamp(2rem, 4vw, 3rem);line-height:1.15;margin:14px 0 10px}
    .sub{font-size:1.1rem;color:#2b3e43}
    .hero-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}
    .btn{appearance:none;border:0;padding:12px 16px;border-radius:14px;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:10px}
    .btn-primary{background:var(--clr-teal);color:#fff;box-shadow:var(--shadow-md)}
    .btn-primary:hover{filter:brightness(1.05);transform:translateY(-1px)}
    .btn-secondary{background:var(--clr-sand);color:#2b3e43}

    @media (max-width: 900px){
      .hero .wrap{grid-template-columns:1fr}
      .hero-art{order:-1}
    }

    section{padding:56px 0}
    .section-title{font-size:1.8rem;margin:0 0 10px}
    .section-kicker{color:#33565c;font-weight:800;letter-spacing:.8px;text-transform:uppercase;font-size:.85rem}

    /* Services grid */
    .services{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
    .card{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:22px;padding:18px;box-shadow:var(--shadow-sm);position:relative;overflow:hidden}
    .card::after{content:"";position:absolute;right:-28px;top:-28px;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle at 30% 30%, #ffffffAA, transparent 60%), var(--clr-sand);filter:blur(2px)}
    .chip{display:inline-block;background:rgba(15,76,92,.08);padding:4px 8px;border-radius:999px;font-weight:700;font-size:.8rem}
    .card ul{padding-left:18px;margin:12px 0}
    .card .btn{margin-top:8px}
    @media (max-width: 1000px){.services{grid-template-columns:1fr 1fr}}
    @media (max-width: 720px){.services{grid-template-columns:1fr}}

    /* Program tiers */
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
    .tier{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:22px;padding:20px;box-shadow:var(--shadow-sm)}
    .tier h4{margin:0 0 6px}
    .pill{display:inline-block;background:rgba(255,138,91,.14);padding:4px 8px;border-radius:999px;font-weight:700;font-size:.8rem;color:#7a3a23;border:1px dashed #ffb79d}
    .tier ul{padding-left:18px;margin:12px 0}
    .tier .btn{margin-top:8px}
    .tier.featured{border:2px solid var(--clr-accent);box-shadow:var(--shadow-md)}

    /* Benefits ribbon */
    .ribbon{background:linear-gradient(90deg, #fff7ef, #eefbf7);border:1px solid #ffe2d6;border-radius:22px;padding:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;align-items:center}
    .ribbon-item{display:flex;align-items:center;gap:10px}
    .dot{width:10px;height:10px;border-radius:50%;background:var(--clr-accent)}
    @media (max-width: 900px){.ribbon{grid-template-columns:1fr 1fr}}
    @media (max-width: 520px){.ribbon{grid-template-columns:1fr}}

    /* Testimonials */
    .testi{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
    .quote{background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:20px;padding:18px;box-shadow:var(--shadow-sm)}
    .quote p{margin:0 0 10px}
    .person{display:flex;align-items:center;gap:10px}
    .avatar{width:42px;height:42px;border-radius:50%;background:url('assets/img/avatar.svg') center/cover no-repeat, var(--clr-sand);border:2px solid #fff;box-shadow:var(--shadow-sm)}
    @media (max-width: 860px){.testi{grid-template-columns:1fr}}

    /* FAQ */
    .faq{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .faq .q{background:#fff;border:1px solid rgba(15,76,92,.1);border-radius:16px}
    .faq button{all:unset;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 16px;cursor:pointer}
    .faq button:focus-visible{outline:3px solid var(--clr-accent);border-radius:14px}
    .faq .icon{flex:0 0 34px;height:34px;border-radius:10px;background:var(--clr-mint);display:grid;place-items:center;font-weight:900;color:#1c3f46}
    .faq .a{max-height:0;overflow:hidden;transition:max-height .28s ease}
    .faq .a-inner{padding:0 16px 14px}
    .faq .open .a{max-height:260px}
    @media (max-width: 900px){.faq{grid-template-columns:1fr}}

    /* Newsletter */
    .newsletter{background:linear-gradient(135deg, #fefefe, #fff7ef);border:1px solid #ffe2d6;border-radius:22px;padding:20px;display:grid;grid-template-columns:1.2fr .8fr;gap:16px;box-shadow:var(--shadow-sm)}
    .newsletter form{display:flex;gap:10px;flex-wrap:wrap}
    .field{flex:1 1 220px;min-width:200px}
    input[type=email]{width:100%;padding:12px 14px;border-radius:12px;border:1px solid rgba(15,76,92,.18);font:inherit}
    .hint{font-size:.85rem;color:#8a4b38}
    @media (max-width: 860px){.newsletter{grid-template-columns:1fr}}

    /* CTA Banner */
    .cta-banner{background:linear-gradient(90deg, var(--clr-teal), #145d70);color:#eafff8;border-radius:24px;padding:22px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:14px}
    .cta-banner .btn{background:#fff;color:#0f3942}
    @media (max-width: 720px){.cta-banner{grid-template-columns:1fr}}

    footer{padding:36px 0 56px}
    .foot{display:grid;grid-template-columns:1.2fr .8fr;gap:20px}
    .foot .mini{display:grid;gap:8px}
    .foot a{color:var(--clr-teal-ink)}
    .small{font-size:.92rem;color:#375a60}
    @media (max-width: 900px){.foot{grid-template-columns:1fr}}
  </style>
</head>
